bool isPalindrome(int x) {
  int n, d, k = 0;

  if (x < 0) return false;

  n = x;
  while (n) {
    d = n % 10;
    if (k > (0x7fffffff - d) / 10) return false; // overflow
    k = k * 10 + d;
    n = n / 10;
  }

  return (k == x);
}

class Solution {
public:
  bool isPalindrome(int x) {
    if (x < 0) return false;
    long long k = 0;
    int n = x;
    while (n > 0) {
      k = k * 10 + n % 10;
      n /= 10;
    }
    return k == x;
  }
};

