class Solution:
    def isPalindrome(self, x: int) -> bool:
        if x < 0:
            return False
        return str(x) == str(x)[::-1]

impl Solution {
  pub fn is_palindrome(x: i32) -> bool {
    if x < 0 {
      return false;
    }
    let (mut n, mut k) = (x, 0i64);
    while n > 0 {
      k = k * 10 + (n % 10) as i64;
      n /= 10;
    }
    k == x as i64
  }
}

const isPalindrome = (x: number): boolean => {
  if (x < 0) return false;
  return String(x) === String(x).split('').reverse().join('');
};
